definite_clear.source:
def _view(mount):
    return mount["source"], mount["target"], mount["writable"]
def public(adapter, other, condition):
    landing = []
    for mount in getattr(adapter, "mounts", None):
        landing.append(mount)
    alias = landing
    alias.clear()
    _view(landing[0])

